//! Replays the cases generated by the Lean Storage name reference.

use fireemu_core_storage::name::{BucketName, NameError, ObjectName, bucket_name_violation};
use fireemu_core_types::codec::hex_decode;

fn result<T>(
    result: Result<T, NameError>,
    input: &str,
    as_str: impl FnOnce(&T) -> &str,
) -> &'static str {
    match result {
        Ok(value) => {
            assert_eq!(
                as_str(&value),
                input,
                "validated names preserve their spelling"
            );
            "ok"
        }
        Err(NameError::Empty) => "empty",
        Err(NameError::TooLong) => "long",
        Err(NameError::ControlCharacter) => "control",
        Err(NameError::Dot) => "dot",
        Err(NameError::ReservedPrefix) => "object-reserved",
        Err(NameError::InvalidBucketCharacter) => "bucket-character",
    }
}

#[test]
fn storage_name_validators_follow_the_lean_reference() {
    let fixture = include_str!("fixtures/lean-storage-names.corpus");
    let mut rows = fixture.lines();
    let count: usize = rows
        .next()
        .unwrap()
        .strip_prefix("# ")
        .unwrap()
        .parse()
        .unwrap();
    assert!(count >= 100);
    assert_eq!(rows.clone().count(), count);
    for row in rows {
        let [id, kind, encoded, expected]: [&str; 4] = row
            .split('\t')
            .collect::<Vec<_>>()
            .try_into()
            .expect("case, kind, input, output");
        let input = String::from_utf8(hex_decode(encoded).expect("hexadecimal")).expect("UTF-8");
        let actual = match kind {
            "object" => result(ObjectName::try_new(&input), &input, ObjectName::as_str),
            "bucket" => result(BucketName::try_new(&input), &input, BucketName::as_str),
            "strict" => bucket_name_violation(&input).unwrap_or("ok"),
            _ => panic!("unknown validator {kind}"),
        };
        assert_eq!(actual, expected, "fixture {id}");
    }
}
